    image_patch = ImagePatch(image)
    benches = image_patch.find("bench")
    shadows = image_patch.find("shadow")
    if not benches or not shadows: return image_patch

    # Find the bench part near each shadow
    near_shadow_benches = []
    for bench in benches:
        for shadow in shadows:
            if bench.overlaps_with(shadow.left, shadow.lower, shadow.right, shadow.upper):
                near_shadow_benches.append(bench)
                break

    return near_shadow_benches[0] if near_shadow_benches else benches[0]

